#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Credentials live in the Windows user profile, not in the git repo.
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
cd "$REPO_ROOT"

OCI_DIR="${HOME}/.oci"
KEY_FILE="${OCI_DIR}/oci_api_key.pem"
PUB_FILE="${OCI_DIR}/oci_api_key_public.pem"
CFG_FILE="${OCI_DIR}/config"
ENV_FILE="${OCI_DIR}/wattloft.env"
REQUIRED_REGION="sa-saopaulo-1"

mkdir -p "$OCI_DIR"

TOTAL_STAGES=8

banner "Wattloft OCI: let an agent act as you (Always Free)"

# ── 1. Home region (irreversible; Always Free only works here) ───────────
stage "Home region must be Brazil East (Sao Paulo)"
say "Always Free compute, HeatWave, and Vault only exist in the tenancy home region."
say "Oracle cannot change home region after signup. Issue #7 needs Brazil East (Sao Paulo)."
open_url "https://cloud.oracle.com/tenancy?region=${REQUIRED_REGION}"
step "Sign in if asked."
step "On Tenancy Details, find Home Region (under Tenancy Information)."
step "The region picker at the top of the Console should also read Brazil East (Sao Paulo)."
pause "Press Enter when you can see Home Region."
if ! confirm "Is Home Region Brazil East (Sao Paulo) / Brazil East (São Paulo)?"; then
  warn "Stop. A later agent must not pick another region or upgrade to PAYG to chase capacity."
  warn "ADR 0020: unexpected invoice or no Always Free instance after a week → Lightsail, not billable OCI."
  exit 1
fi
write_env OCI_REGION "$REQUIRED_REGION"

# ── 2. Stay Always Free (no PAYG) ────────────────────────────────────────
stage "Do not upgrade to Pay As You Go"
say "Free Tier is what we want. The Console will nag you to Upgrade. Never do that for Wattloft."
say "During the 30-day trial you have \$300 credits: do not spend them on paid shapes."
open_url "https://cloud.oracle.com/?region=${REQUIRED_REGION}"
step "Look at the top of the Console. If you see an Upgrade / Pay As You Go banner, ignore it."
step "Optional: open the hamburger menu, search Subscriptions, and confirm the account is Free Tier."
if ! confirm "Will you leave this tenancy Always Free-only (no Upgrade, no PAYG)?"; then
  warn "Issue #7 forbids PAYG. Stopping."
  exit 1
fi
write_env OCI_ALWAYS_FREE_ONLY "yes"

# ── 3. \$1 budget tripwire ───────────────────────────────────────────────
stage "Budget alert at \$1"
say "This is a smoke alarm, not a spending plan. Always Free usage should stay at \$0."
say "If anything billable appears (paid VM, virtual private vault, extra region), email fires."
open_url "https://cloud.oracle.com/usage/budgets?region=${REQUIRED_REGION}"
step "If the page is empty, use the hamburger menu and search Budgets (Billing & Cost Management)."
step "If a budget named always-free-tripwire already exists, skip Create and press Enter at the pause."
step "Create Budget → Budget Scope: Compartment → Target: your tenancy (the root compartment)."
step "Name: always-free-tripwire"
step "Monthly, Budget Amount: 1 (minimum Oracle allows)."
step "In Budget Alert Rule: Threshold Metric = Actual Spend; Threshold Type = Percentage of Budget; Threshold % = 1."
step "Email Recipients: an inbox you actually read. Create."
pause "Press Enter after the budget exists (or already existed)."
ask BUDGET_ALERT_EMAIL "Email that will receive the alert:"
write_env BUDGET_ALERT_EMAIL "$BUDGET_ALERT_EMAIL"

# ── 4. Compartment wattloft ──────────────────────────────────────────────
stage "Compartment wattloft"
say "The later agent will put the VM, VCN, HeatWave, Bastion, Vault, and Object Storage here."
open_url "https://cloud.oracle.com/identity/compartments?region=${REQUIRED_REGION}"
step "If wattloft is already in the list, open it and skip Create."
step "Otherwise: Create Compartment."
step "Name: wattloft"
step "Description: Wattloft Always Free pet (GitHub issue 7)"
step "Parent Compartment: the tenancy root (already selected on a new account)."
step "Create, then click wattloft and Copy the OCID (starts with ocid1.compartment.oc1.)."
pause "Press Enter when you have the compartment OCID."
ask OCI_COMPARTMENT_OCID "Paste the wattloft compartment OCID:"
if [[ "$OCI_COMPARTMENT_OCID" != ocid1.compartment.* ]]; then
  warn "That does not look like a compartment OCID (ocid1.compartment.oc1....)."
  ask OCI_COMPARTMENT_OCID "Paste the wattloft compartment OCID:"
fi
write_env OCI_COMPARTMENT_OCID "$OCI_COMPARTMENT_OCID"

# ── 5. API signing key + ~/.oci/config ───────────────────────────────────
stage "API signing key for the agent"
say "This key is how a Cursor agent and GitHub Actions call OCI as you. It is not an SSH key."
say "Generated locally with no passphrase so unattended agents can use it."
if [[ ! -f "$KEY_FILE" ]]; then
  if ! command -v openssl >/dev/null 2>&1; then
    warn "openssl not found. Install Git for Windows (includes openssl) and re-run."
    exit 1
  fi
  openssl genrsa -out "$KEY_FILE" 2048
  chmod go-rwx "$KEY_FILE" 2>/dev/null || true
  openssl rsa -pubout -in "$KEY_FILE" -out "$PUB_FILE"
  note "wrote $KEY_FILE"
else
  note "reusing existing $KEY_FILE"
  [[ -f "$PUB_FILE" ]] || openssl rsa -pubout -in "$KEY_FILE" -out "$PUB_FILE"
fi
if command -v clip.exe >/dev/null 2>&1; then
  clip.exe < "$PUB_FILE"
  note "public key copied to the clipboard"
fi
say "Public key (paste this in the Console):"
printf '\n'
sed 's/^/  /' "$PUB_FILE"
printf '\n'
open_url "https://cloud.oracle.com/?region=${REQUIRED_REGION}"
step "Profile menu (person icon, top right) → User settings."
step "Tokens and keys (or Resources → API Keys) → Add API Key."
step "Choose Paste a public key, paste the PEM block, Add."
step "A Configuration File Preview appears. Leave that dialog open."
step "Copy user= (your user OCID) and tenancy= (tenancy OCID) from the snippet."
step "Confirm the fingerprint in the dialog matches the one printed below."
OCI_FINGERPRINT="$(openssl rsa -pubout -outform DER -in "$KEY_FILE" 2>/dev/null | openssl md5 -c | awk '{print $NF}')"
note "expected fingerprint: $OCI_FINGERPRINT"
pause "Press Enter after the public key is added."
ask OCI_CLI_USER "Paste the user OCID (user= ...):"
ask OCI_CLI_TENANCY "Paste the tenancy OCID (tenancy= ...):"
if ! confirm "Does the Console fingerprint match the expected one above?"; then
  ask OCI_FINGERPRINT "Paste the fingerprint from the Console:"
fi
if [[ "$OCI_CLI_USER" != ocid1.user.* || "$OCI_CLI_TENANCY" != ocid1.tenancy.* || -z "$OCI_FINGERPRINT" ]]; then
  warn "Need a user OCID (ocid1.user...), a tenancy OCID (ocid1.tenancy...), and a fingerprint."
  exit 1
fi
if command -v cygpath >/dev/null 2>&1; then
  KEY_FILE_CFG="$(cygpath -w "$KEY_FILE")"
  KEY_FILE_CFG="${KEY_FILE_CFG//\\//}"
else
  KEY_FILE_CFG="$KEY_FILE"
fi
cat > "$CFG_FILE" <<EOF
[DEFAULT]
user=${OCI_CLI_USER}
fingerprint=${OCI_FINGERPRINT}
key_file=${KEY_FILE_CFG}
tenancy=${OCI_CLI_TENANCY}
region=${REQUIRED_REGION}
EOF
chmod go-rwx "$CFG_FILE" 2>/dev/null || true
note "wrote $CFG_FILE"
write_env OCI_CLI_USER "$OCI_CLI_USER"
write_env OCI_CLI_TENANCY "$OCI_CLI_TENANCY"
write_env OCI_FINGERPRINT "$OCI_FINGERPRINT"
write_env OCI_KEY_FILE "$KEY_FILE_CFG"

# ── 6. Install OCI CLI ───────────────────────────────────────────────────
stage "Install OCI CLI"
say "The later agent talks to Oracle with the oci command. This takes a few minutes."
if command -v oci >/dev/null 2>&1; then
  note "oci already on PATH: $(command -v oci)"
else
  if command -v powershell.exe >/dev/null 2>&1; then
    step "Running Oracle's Windows installer with defaults (Python + oci.exe)."
    if ! powershell.exe -NoProfile -ExecutionPolicy Bypass -Command \
      "Invoke-WebRequest https://raw.githubusercontent.com/oracle/oci-cli/master/scripts/install/install.ps1 -OutFile \$env:TEMP\\oci-install.ps1; & \$env:TEMP\\oci-install.ps1 -AcceptAllDefaults"; then
      SKIPPED+=("OCI CLI install (run install.ps1 -AcceptAllDefaults as Admin, or: py -m pip install --user oci-cli)")
      warn "CLI installer failed. The later agent can install it once ~/.oci/config exists."
    fi
  else
    SKIPPED+=("OCI CLI install (PowerShell not found)")
    warn "Could not run the Windows installer from this shell."
  fi
fi
# Typical Windows install location after a fresh install.ps1
export PATH="${PATH}:${HOME}/bin:${HOME}/AppData/Local/Programs:${USERPROFILE:-}/bin"
hash -r 2>/dev/null || true

# ── 7. Smoke test ────────────────────────────────────────────────────────
stage "Smoke test the API key"
say "If this works, a later agent can create the VCN, VM, HeatWave, Bastion, and Vault."
if command -v oci >/dev/null 2>&1; then
  if oci iam region list --output table >/dev/null; then
    note "iam region list: ok"
  else
    warn "oci iam region list failed. Check the public key is on the user and the fingerprint matches."
    SKIPPED+=("OCI smoke test (oci iam region list)")
  fi
  if oci iam compartment get --compartment-id "$OCI_COMPARTMENT_OCID" >/dev/null; then
    note "compartment wattloft: reachable"
  else
    warn "Could not read the wattloft compartment. Recheck the OCID."
    SKIPPED+=("OCI smoke test (compartment get)")
  fi
else
  warn "oci not on PATH yet. Open a new terminal after install, or let the later agent install the CLI."
  SKIPPED+=("OCI CLI not on PATH for smoke test")
fi
pause "Press Enter to continue."

# ── 8. GitHub Actions secrets (issue #7 deploy) ──────────────────────────
stage "GitHub Actions secrets"
say "Issue #7's deploy job uses oracle-actions/run-oci-cli-command, which reads these names."
say "Compartment OCID is a variable (not secret). The PEM private key is a secret."
set_secret OCI_CLI_USER "$OCI_CLI_USER"
set_secret OCI_CLI_TENANCY "$OCI_CLI_TENANCY"
set_secret OCI_CLI_FINGERPRINT "$OCI_FINGERPRINT"
set_secret OCI_CLI_REGION "$REQUIRED_REGION"
OCI_CLI_KEY_CONTENT="$(cat "$KEY_FILE")"
set_secret OCI_CLI_KEY_CONTENT "$OCI_CLI_KEY_CONTENT"
unset OCI_CLI_KEY_CONTENT
set_var OCI_COMPARTMENT_OCID "$OCI_COMPARTMENT_OCID"

cat > "${OCI_DIR}/wattloft-agent.txt" <<EOF
Wattloft OCI — credentials for an agent implementing GitHub issue #7.

Config: ${CFG_FILE}
Key:    ${KEY_FILE}
Region: ${REQUIRED_REGION} (Brazil East / Sao Paulo) — home region, Always Free only.
Compartment name: wattloft
Compartment OCID: ${OCI_COMPARTMENT_OCID}

Do not: click Upgrade / PAYG, subscribe extra regions, create a Network Load Balancer,
create a virtual private vault, enable HeatWave analytics, or open public TCP 22.

Do: Ampere A1 Flex 2 OCPU / 12 GB (VM.Standard.E2.1.Micro if out of capacity);
HeatWave shape MySQL.Free in a private subnet with no public IP; reserved public IPv4
on the VM VNIC; Bastion for GitHub Actions; default Vault + software keys; Object
Storage dumps (20 GB Always Free). Unexpected invoice or no instance after a week of
capacity retries: stop and use Lightsail dual-stack nano, do not improvise billable OCI.

GitHub Actions (oracle-actions/run-oci-cli-command): secrets OCI_CLI_USER,
OCI_CLI_TENANCY, OCI_CLI_FINGERPRINT, OCI_CLI_KEY_CONTENT, OCI_CLI_REGION;
variable OCI_COMPARTMENT_OCID.
EOF
note "wrote ${OCI_DIR}/wattloft-agent.txt for the later agent session"

# ──────────────────────────────────────────────────────────────────────────

finish
note "Private key stays in ${KEY_FILE} — never commit it."
note "Next: a later agent implements https://github.com/uldercarrilho/wattloft/issues/7"
printf '\n'
